UNITS = UNITS_PART1 + UNITS_PART2 + UNITS_PART3 + UNITS_PART4 + UNITS_PART5


class Command(BaseCommand):
    help = "Seed Vocabulary Builder Book 2 units (order 31-60), words, questions and passages."

    def handle(self, *args, **options):
        units_created = 0
        words_created = 0
        questions_created = 0
        passages_created = 0
        pq_created = 0

        for order, unit_data in enumerate(UNITS, start=31):
            unit, was_created = VBUnit.objects.get_or_create(
                name=unit_data['name'],
                defaults={
                    'order': order, 'icon': unit_data['icon'],
                    'description': unit_data['description'],
                },
            )
            if was_created:
                units_created += 1
            else:
                unit.order = order
                unit.icon = unit_data['icon']
                unit.description = unit_data['description']
                unit.save()

            for w_order, (word, pron, pos, definition, example) in enumerate(unit_data['words'], start=1):
                word_obj, w_created = VBWord.objects.get_or_create(
                    unit=unit, word=word,
                    defaults={
                        'pronunciation': pron, 'part_of_speech': pos,
                        'definition': definition, 'example_sentence': example,
                        'order': w_order,
                    },
                )
                if w_created:
                    words_created += 1
                else:
                    word_obj.pronunciation = pron
                    word_obj.part_of_speech = pos
                    word_obj.definition = definition
                    word_obj.example_sentence = example
                    word_obj.order = w_order
                    word_obj.save()

            for prompt, options, correct_answer in unit_data['questions']:
                _, q_created = VBQuestion.objects.get_or_create(
                    unit=unit, prompt=prompt, correct_answer=correct_answer,
                    defaults={'options': options},
                )
                if q_created:
                    questions_created += 1

            passage_data = unit_data['passage']
            passage, p_created = VBPassage.objects.get_or_create(
                unit=unit,
                defaults={'title': passage_data['title'], 'body': passage_data['body']},
            )
            if p_created:
                passages_created += 1
            else:
                passage.title = passage_data['title']
                passage.body = passage_data['body']
                passage.save()

            for prompt, options, correct_answer in passage_data['questions']:
                _, pq_c = VBPassageQuestion.objects.get_or_create(
                    passage=passage, prompt=prompt, correct_answer=correct_answer,
                    defaults={'options': options},
                )
                if pq_c:
                    pq_created += 1

        self.stdout.write(self.style.SUCCESS(
            f"Seeded {units_created} new units, {words_created} new words, "
            f"{questions_created} new questions, {passages_created} new passages, "
            f"{pq_created} new passage questions "
            f"({VBUnit.objects.count()} units, {VBWord.objects.count()} words, "
            f"{VBQuestion.objects.count()} questions, {VBPassageQuestion.objects.count()} "
            f"passage questions total)."
        ))
